// base64hub MCP server for Cloudflare Workers: https://mcp.base64hub.com/mcp
// Generated by scripts/build-worker.js from core.js, protocol.js and http.js. Do not edit.

// ---- core.js ----
// Base64 core, copied from the base64hub npm package (encode, decode, validate).
// Behavior follows the shared base64hub contract; see testdata/vectors.json.

const STD = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const URL_SAFE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

const STD_CODES = codes(STD);
const URL_CODES = codes(URL_SAFE);
const PAD = 61; // '='
const LF = 10;

// ASCII code -> 6-bit value for both alphabets, -1 for anything else.
const VALUES = new Int8Array(128).fill(-1);
for (let i = 0; i < 64; i++) {
  VALUES[STD.charCodeAt(i)] = i;
  VALUES[URL_SAFE.charCodeAt(i)] = i;
}

const utf8 = new TextEncoder();
const ascii = new TextDecoder();

function codes(alphabet) {
  const out = new Uint8Array(64);
  for (let i = 0; i < 64; i++) out[i] = alphabet.charCodeAt(i);
  return out;
}

/** Error thrown by decode() for input that is not valid Base64. */
class Base64Error extends Error {
  constructor(message, position) {
    super(message);
    this.name = 'Base64Error';
    if (position !== undefined) this.position = position;
  }
}

function toBytes(input) {
  if (typeof input === 'string') return utf8.encode(input);
  if (input instanceof Uint8Array) return input;
  if (input instanceof ArrayBuffer) return new Uint8Array(input);
  if (ArrayBuffer.isView(input)) return new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
  throw new TypeError('expected a string, Uint8Array, ArrayBuffer or ArrayBufferView');
}

/**
 * Encode bytes (or the UTF-8 bytes of a string) to Base64.
 * Options: url (URL-safe alphabet), pad (default true), wrap (line length, 0 = none).
 */
function encode(input, { url = false, pad = true, wrap = 0 } = {}) {
  const bytes = toBytes(input);
  if (!Number.isInteger(wrap) || wrap < 0) throw new RangeError('wrap must be a non-negative integer');
  const abc = url ? URL_CODES : STD_CODES;
  const len = bytes.length;
  const rest = len % 3;
  const full = len - rest;
  const size = pad ? Math.ceil(len / 3) * 4 : full / 3 * 4 + (rest ? rest + 1 : 0);
  const out = new Uint8Array(size);
  let j = 0;
  for (let i = 0; i < full; i += 3) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2];
    out[j++] = abc[n >> 18];
    out[j++] = abc[(n >> 12) & 63];
    out[j++] = abc[(n >> 6) & 63];
    out[j++] = abc[n & 63];
  }
  if (rest) {
    const n = (bytes[full] << 16) | (rest === 2 ? bytes[full + 1] << 8 : 0);
    out[j++] = abc[n >> 18];
    out[j++] = abc[(n >> 12) & 63];
    if (rest === 2) out[j++] = abc[(n >> 6) & 63];
    else if (pad) out[j++] = PAD;
    if (pad) out[j++] = PAD;
  }
  if (wrap === 0 || size <= wrap) return ascii.decode(out);
  const wrapped = new Uint8Array(size + Math.floor((size - 1) / wrap));
  let k = 0;
  for (let i = 0; i < size; i += wrap) {
    if (i) wrapped[k++] = LF;
    const line = out.subarray(i, i + wrap);
    wrapped.set(line, k);
    k += line.length;
  }
  return ascii.decode(wrapped);
}

// Whitespace is exactly space, tab, CR and LF.
const isSpace = (c) => c === 32 || c === 9 || c === 13 || c === 10;

// The ";base64," of a data URI prefix is looked for within this many bytes, as in the Go build.
const HEADER_WINDOW = 64 * 1024;
const MARKER = utf8.encode(';base64,');
const DATA = utf8.encode('data:');

function textBytes(text) {
  if (typeof text === 'string') return utf8.encode(text);
  if (text instanceof Uint8Array) return text;
  if (text instanceof ArrayBuffer) return new Uint8Array(text);
  if (ArrayBuffer.isView(text)) return new Uint8Array(text.buffer, text.byteOffset, text.byteLength);
  throw new TypeError('expected a string or bytes');
}

// Index where the Base64 payload starts: after leading whitespace and, when the input starts
// with "data:" (any case), after the first ";base64," (literal, lower case).
function payloadStart(b) {
  let i = 0;
  while (i < b.length && isSpace(b[i])) i++;
  if (b.length - i < DATA.length) return i;
  for (let k = 0; k < DATA.length; k++) {
    const c = b[i + k];
    if ((c >= 65 && c <= 90 ? c | 32 : c) !== DATA[k]) return i;
  }
  const end = Math.min(b.length, i + HEADER_WINDOW) - MARKER.length;
  outer: for (let j = i; j <= end; j++) {
    for (let k = 0; k < MARKER.length; k++) if (b[j + k] !== MARKER[k]) continue outer;
    return j + MARKER.length;
  }
  return i;
}

const fatal = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true });
const hex = (n, width) => n.toString(16).padStart(width, '0');
const isPrint = (ch) => ch === ' ' || /^[\p{L}\p{M}\p{N}\p{P}\p{S}]$/u.test(ch);

// One code point escaped the way Go's strconv.QuoteRune does it, without the quotes.
function quoteRune(cp) {
  const ch = String.fromCodePoint(cp);
  if (ch === "'" || ch === '\\') return '\\' + ch;
  if (isPrint(ch)) return ch;
  const esc = { 7: '\\a', 8: '\\b', 12: '\\f', 10: '\\n', 13: '\\r', 9: '\\t', 11: '\\v' }[cp];
  if (esc) return esc;
  if (cp < 32 || cp === 127) return '\\x' + hex(cp, 2);
  if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;
  return cp < 0x10000 ? '\\u' + hex(cp, 4) : '\\U' + hex(cp, 8);
}

// The character starting at b[i], quoted like Go's %q of a rune; a byte that does not start a
// valid UTF-8 sequence is shown as '\xNN'.
function describe(b, i) {
  for (let n = 1; n <= 4 && i + n <= b.length; n++) {
    let s;
    try {
      s = fatal.decode(b.subarray(i, i + n));
    } catch {
      continue;
    }
    if (s.length > 0) return `'${quoteRune(s.codePointAt(0))}'`;
  }
  return `'\\x${hex(b[i], 2)}'`;
}

// Decodes left to right, like the Go build's streaming decoder, so the first problem in the
// input is the one reported. Writes into `out` when given. Returns the validate fields.
function scan(b, out) {
  const fail = (message, position) => {
    throw new Base64Error(message, position);
  };
  let n = 0; // characters in the current group of four
  let pos = 0; // position in the cleaned text
  let pads = 0;
  let padPos = 0;
  let std = false;
  let url = false;
  let total = 0;
  let acc = 0;
  for (let i = payloadStart(b); i < b.length; i++) {
    const c = b[i];
    if (isSpace(c)) continue;
    if (c === PAD) {
      if (pads === 0) padPos = pos;
      pads++;
      pos++;
      continue;
    }
    if (pads > 0) fail(`unexpected '=' at position ${padPos}: padding is only allowed at the end`, padPos);
    const v = c < 128 ? VALUES[c] : -1;
    if (v < 0) fail(`invalid character ${describe(b, i)} at position ${pos}`, pos);
    if (c === 43 || c === 47) std = true;
    else if (c === 45 || c === 95) url = true;
    acc = (acc << 6) | v;
    n++;
    pos++;
    if (n === 4) {
      if (out) {
        out[total] = acc >> 16;
        out[total + 1] = acc >> 8;
        out[total + 2] = acc;
      }
      total += 3;
      n = 0;
      acc = 0;
    }
  }
  if (pads > 2) fail(`too much padding: ${pads} '=' at position ${padPos}, at most 2 are allowed`, padPos);
  if (n === 1) {
    const len = pos - pads;
    fail(`invalid length: ${len} characters leave a single character in the last group`, len - 1);
  }
  if (n > 1) {
    acc <<= 6 * (4 - n);
    if (out) {
      out[total] = acc >> 16;
      if (n === 3) out[total + 1] = acc >> 8;
    }
    total += n - 1;
  }
  const variant = std && url ? 'mixed' : std ? 'standard' : url ? 'url' : 'either';
  return { variant, padded: pos % 4 === 0, bytes: total };
}

/**
 * Decode Base64 text (a string, or its bytes) to bytes. Lenient: either alphabet, optional
 * padding, spaces, tabs, CR, LF and a data: URI prefix are accepted. Throws Base64Error.
 */
function decode(text) {
  const b = textBytes(text);
  const out = new Uint8Array(Math.floor((b.length * 3) / 4) + 3);
  const { bytes } = scan(b, out);
  return out.slice(0, bytes);
}

/**
 * Check Base64 text without throwing.
 * Valid: { valid: true, variant, padded, bytes }. Invalid: { valid: false, error }.
 */
function validate(text) {
  try {
    return { valid: true, ...scan(textBytes(text), null) };
  } catch (err) {
    if (err instanceof Base64Error) return { valid: false, error: err.message };
    throw err;
  }
}

// ---- protocol.js ----
// MCP protocol layer: JSON-RPC 2.0 messages in, JSON-RPC 2.0 messages out.
// Dual-era: answers modern stateless requests (per-request _meta, server/discover)
// and the legacy initialize handshake. Transport-free and runtime-neutral: the stdio
// server (server.js) and the HTTP Worker (http.js) both build on createProtocol().

/** Revisions with per-request metadata (no initialize). */
const MODERN_VERSIONS = ['2026-07-28'];
/** Revisions that start with the initialize handshake, newest first. */
const LEGACY_VERSIONS = ['2025-11-25', '2025-06-18', '2025-03-26', '2024-11-05'];
const SUPPORTED_VERSIONS = [...MODERN_VERSIONS, ...LEGACY_VERSIONS];

const META_VERSION = 'io.modelcontextprotocol/protocolVersion';
const META_CAPABILITIES = 'io.modelcontextprotocol/clientCapabilities';
const META_SERVER_INFO = 'io.modelcontextprotocol/serverInfo';

const PARSE_ERROR = -32700;
const INVALID_REQUEST = -32600;
const METHOD_NOT_FOUND = -32601;
const INVALID_PARAMS = -32602;
const INTERNAL_ERROR = -32603;
const HEADER_MISMATCH = -32020;
const UNSUPPORTED_PROTOCOL_VERSION = -32022;

const TOOL_LIST_TTL_MS = 3600000;

const READ_ONLY = { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false };

const TOOLS = [
  {
    name: 'base64_encode',
    title: 'Base64 encode',
    description:
      'Encode text to Base64. The text is converted to UTF-8 bytes first, so any language and emoji ' +
      'work. Set url_safe for the URL- and filename-safe alphabet (- and _ instead of + and /, as in ' +
      "JWTs and URLs), padding=false to drop the trailing '=' characters, and wrap to break the " +
      'output into lines (76 for MIME email). Returns only the Base64 string.',
    inputSchema: {
      type: 'object',
      properties: {
        text: { type: 'string', description: 'Text to encode, taken as UTF-8.' },
        url_safe: {
          type: 'boolean',
          default: false,
          description: 'Use the URL-safe alphabet (- and _, RFC 4648 section 5).',
        },
        padding: { type: 'boolean', default: true, description: "Add '=' padding at the end." },
        wrap: {
          type: 'integer',
          minimum: 0,
          default: 0,
          description: 'Insert a line break after every N output characters. 0 = one line, 76 = MIME.',
        },
      },
      required: ['text'],
      additionalProperties: false,
    },
    annotations: { title: 'Base64 encode', ...READ_ONLY },
    run: ({ text, url_safe = false, padding = true, wrap = 0 }) =>
      textResult(encode(text, { url: url_safe, pad: padding, wrap })),
  },
  {
    name: 'base64_decode',
    title: 'Base64 decode',
    description:
      'Decode Base64 back to text. Accepts the standard and the URL-safe alphabet (even mixed), ' +
      "missing '=' padding, spaces and line breaks, and data URIs such as data:image/png;base64,... " +
      'Returns the decoded UTF-8 text exactly. If the bytes are not valid UTF-8 (an image, compressed ' +
      'or encrypted data), says so and returns them as hex instead. Invalid input fails with the ' +
      'reason and the position of the offending character.',
    inputSchema: {
      type: 'object',
      properties: {
        data: { type: 'string', description: 'Base64 text or a data: URI.' },
      },
      required: ['data'],
      additionalProperties: false,
    },
    annotations: { title: 'Base64 decode', ...READ_ONLY },
    run: ({ data }) => {
      let bytes;
      try {
        bytes = decode(data);
      } catch (err) {
        if (err instanceof Base64Error) return errorResult(`Invalid Base64: ${err.message}.`);
        throw err;
      }
      try {
        return textResult(new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes));
      } catch {
        const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
        return textResult(`The data decodes to ${bytes.length} bytes that are not valid UTF-8 text. Hex:\n${hex}`);
      }
    },
  },
  {
    name: 'base64_validate',
    title: 'Base64 validate',
    description:
      'Check whether a string is valid Base64 and describe it, without returning the decoded ' +
      'content. Uses the same lenient rules as base64_decode. Returns JSON: valid, variant ' +
      '(standard if + or / occurs, url if - or _ occurs, mixed if both, either if neither), padded ' +
      "(whether the '=' padding is complete) and bytes (decoded size); or valid: false with the " +
      'error base64_decode would report, such as the offending character and its position.',
    inputSchema: {
      type: 'object',
      properties: {
        data: { type: 'string', description: 'The string to check. A data: URI is accepted too.' },
      },
      required: ['data'],
      additionalProperties: false,
    },
    outputSchema: {
      type: 'object',
      properties: {
        valid: { type: 'boolean' },
        variant: { type: 'string', enum: ['standard', 'url', 'mixed', 'either'] },
        padded: { type: 'boolean' },
        bytes: { type: 'integer', minimum: 0 },
        error: { type: 'string' },
      },
      required: ['valid'],
      additionalProperties: false,
    },
    annotations: { title: 'Base64 validate', ...READ_ONLY },
    run: ({ data }) => {
      const result = validate(data);
      return { content: [{ type: 'text', text: JSON.stringify(result) }], structuredContent: result };
    },
  },
];

const TOOL_BY_NAME = new Map(TOOLS.map((t) => [t.name, t]));
const TOOL_LIST = TOOLS.map(({ run, ...tool }) => tool);

function textResult(text) {
  return { content: [{ type: 'text', text }] };
}

function errorResult(text) {
  return { content: [{ type: 'text', text }], isError: true };
}

class RpcError extends Error {
  constructor(code, message, data) {
    super(message);
    this.code = code;
    this.data = data;
  }
}

const isObject = (v) => typeof v === 'object' && v !== null && !Array.isArray(v);

// Returns a message for the model when the arguments don't match the tool's input schema.
function checkArguments(tool, args) {
  const { properties, required } = tool.inputSchema;
  for (const key of required) {
    if (args[key] === undefined || args[key] === null) return `Missing required argument "${key}".`;
  }
  for (const [key, value] of Object.entries(args)) {
    const prop = properties[key];
    if (!prop) return `Unknown argument "${key}". Allowed arguments: ${Object.keys(properties).join(', ')}.`;
    if (value === null && !required.includes(key)) continue;
    if (prop.type === 'string' && typeof value !== 'string') return `Argument "${key}" must be a string.`;
    if (prop.type === 'boolean' && typeof value !== 'boolean') return `Argument "${key}" must be true or false.`;
    if (prop.type === 'integer' && !(Number.isInteger(value) && value >= (prop.minimum ?? -Infinity))) {
      return `Argument "${key}" must be a whole number, ${prop.minimum ?? 0} or more.`;
    }
  }
  return null;
}

function callTool(params) {
  if (typeof params.name !== 'string') throw new RpcError(INVALID_PARAMS, 'Missing tool name');
  const tool = TOOL_BY_NAME.get(params.name);
  if (!tool) throw new RpcError(INVALID_PARAMS, `Unknown tool: ${params.name}`);
  const args = params.arguments ?? {};
  if (!isObject(args)) throw new RpcError(INVALID_PARAMS, 'Tool arguments must be an object');
  const problem = checkArguments(tool, args);
  if (problem) return errorResult(problem);
  const clean = Object.fromEntries(Object.entries(args).filter(([, v]) => v !== null));
  return tool.run(clean);
}

// Decides how to serve a request: modern (per-request _meta) or legacy (initialize era).
function requestEra(method, params) {
  const meta = isObject(params._meta) ? params._meta : {};
  const version = meta[META_VERSION];
  if (method === 'initialize') return 'legacy';
  if (version === undefined) {
    if (method === 'server/discover') {
      throw new RpcError(INVALID_PARAMS, `Missing _meta "${META_VERSION}"`, { supported: SUPPORTED_VERSIONS });
    }
    return 'legacy';
  }
  if (typeof version !== 'string' || !SUPPORTED_VERSIONS.includes(version)) {
    throw new RpcError(UNSUPPORTED_PROTOCOL_VERSION, 'Unsupported protocol version', {
      supported: SUPPORTED_VERSIONS,
      requested: version,
    });
  }
  if (!MODERN_VERSIONS.includes(version)) return 'legacy';
  if (!isObject(meta[META_CAPABILITIES])) {
    throw new RpcError(INVALID_PARAMS, `Missing _meta "${META_CAPABILITIES}"`);
  }
  return 'modern';
}

function errorResponse(id, err) {
  const error = { code: err.code, message: err.message };
  if (err.data !== undefined) error.data = err.data;
  return { jsonrpc: '2.0', id, error };
}

const validId = (id) => typeof id === 'string' || (typeof id === 'number' && Number.isFinite(id));

/**
 * Builds the protocol handlers for one server identity.
 * `description` and `instructions` differ between the local and the hosted server.
 */
function createProtocol({ name, version, description, instructions }) {
  const SERVER_INFO = {
    name,
    title: 'base64hub',
    version,
    description,
    websiteUrl: 'https://base64hub.com/mcp/',
    icons: [
      { src: 'https://base64hub.com/favicon.svg', mimeType: 'image/svg+xml', sizes: ['any'] },
      { src: 'https://base64hub.com/web-app-manifest-512x512.png', mimeType: 'image/png', sizes: ['512x512'] },
    ],
  };
  const INSTRUCTIONS = instructions;

  function initialize(params) {
    const requested = params.protocolVersion;
    if (typeof requested !== 'string') throw new RpcError(INVALID_PARAMS, 'Missing protocolVersion');
    return {
      protocolVersion: LEGACY_VERSIONS.includes(requested) ? requested : LEGACY_VERSIONS[0],
      capabilities: { tools: { listChanged: false } },
      serverInfo: SERVER_INFO,
      instructions: INSTRUCTIONS,
    };
  }

  function dispatch(method, params, era) {
    const modern = era === 'modern';
    switch (method) {
      case 'initialize':
        return initialize(params);
      case 'server/discover':
        return {
          supportedVersions: SUPPORTED_VERSIONS,
          capabilities: { tools: {} },
          instructions: INSTRUCTIONS,
          ttlMs: TOOL_LIST_TTL_MS,
          cacheScope: 'public',
        };
      case 'ping':
        return {};
      case 'tools/list':
        return modern ? { tools: TOOL_LIST, ttlMs: TOOL_LIST_TTL_MS, cacheScope: 'public' } : { tools: TOOL_LIST };
      case 'tools/call':
        return callTool(params);
      default:
        throw new RpcError(METHOD_NOT_FOUND, `Method not found: ${method}`);
    }
  }

  /** Handles one parsed JSON-RPC message. Returns the response object, or null for none. */
  function handleMessage(msg, log = () => {}) {
    if (!isObject(msg)) return errorResponse(null, new RpcError(INVALID_REQUEST, 'Invalid Request'));
    const hasId = 'id' in msg;
    const id = hasId && validId(msg.id) ? msg.id : null;
    if (msg.jsonrpc !== '2.0') return errorResponse(id, new RpcError(INVALID_REQUEST, 'Invalid Request: jsonrpc must be "2.0"'));
    if (!('method' in msg)) {
      // A response from the client; this server never sends requests, so there is nothing to match.
      if (hasId && ('result' in msg || 'error' in msg)) return null;
      return errorResponse(id, new RpcError(INVALID_REQUEST, 'Invalid Request: missing method'));
    }
    if (typeof msg.method !== 'string') return errorResponse(id, new RpcError(INVALID_REQUEST, 'Invalid Request: method must be a string'));
    if (!hasId) return null; // Notifications (initialized, cancelled, ...) need no answer.
    if (id === null) return errorResponse(null, new RpcError(INVALID_REQUEST, 'Invalid Request: id must be a string or number'));

    try {
      if (msg.params !== undefined && !isObject(msg.params)) throw new RpcError(INVALID_PARAMS, 'params must be an object');
      const params = msg.params ?? {};
      const era = requestEra(msg.method, params);
      let result = dispatch(msg.method, params, era);
      if (era === 'modern' || msg.method === 'server/discover') {
        const info = msg.method === 'server/discover' ? SERVER_INFO : { name, version };
        result = { resultType: 'complete', ...result, _meta: { [META_SERVER_INFO]: info } };
      }
      return { jsonrpc: '2.0', id, result };
    } catch (err) {
      if (err instanceof RpcError) return errorResponse(id, err);
      log(`internal error in ${msg.method}: ${err && err.stack ? err.stack : err}`);
      return errorResponse(id, new RpcError(INTERNAL_ERROR, 'Internal error'));
    }
  }

  /** Handles parsed JSON: one message or a batch. Returns a response, an array of them, or null. */
  function handleParsed(msg, log = () => {}) {
    if (!Array.isArray(msg)) return handleMessage(msg, log);
    // JSON-RPC batches (only the 2025-03-26 revision allowed them).
    if (msg.length === 0) return errorResponse(null, new RpcError(INVALID_REQUEST, 'Invalid Request: empty batch'));
    const out = msg.map((m) => handleMessage(m, log)).filter((r) => r !== null);
    return out.length ? out : null;
  }

  /** Handles one line of the stdio stream. Returns the line to write back (without newline), or null. */
  function handleLine(line, log = () => {}) {
    if (!line.trim()) return null;
    let msg;
    try {
      msg = JSON.parse(line);
    } catch {
      return JSON.stringify(errorResponse(null, new RpcError(PARSE_ERROR, 'Parse error')));
    }
    const response = handleParsed(msg, log);
    return response === null ? null : JSON.stringify(response);
  }

  return { handleMessage, handleParsed, handleLine };
}

// ---- http.js ----
// Streamable HTTP binding for the protocol layer, written against the Fetch API so it runs as a
// Cloudflare Worker (worker.js is generated from this file, see scripts/build-worker.js).
// Stateless: every POST is answered with one JSON body, no sessions, no SSE streams.

const MCP_PATH = '/mcp';
const MAX_BODY = 256 * 1024; // 256 KiB keeps the worst case well inside a Worker's CPU budget

const DOCS_URL = 'https://base64hub.com/mcp/';
const CORS_HEADERS = 'Content-Type, Accept, MCP-Protocol-Version, Mcp-Method, Mcp-Name, Mcp-Session-Id, Last-Event-ID';
const SENTINEL_RE = /^=\?base64\?(.*)\?=$/s;
const strictUtf8 = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true });

// Every origin may call this server: it is public, needs no credentials and keeps no state, so
// there is nothing a DNS rebinding or cross-site request could reach that a direct one cannot.
function baseHeaders() {
  return {
    'Access-Control-Allow-Origin': '*',
    'Cache-Control': 'no-store',
    'X-Content-Type-Options': 'nosniff',
  };
}

function json(status, body, extra) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...baseHeaders(), 'Content-Type': 'application/json; charset=utf-8', ...extra },
  });
}

function empty(status, extra) {
  return new Response(null, { status, headers: { ...baseHeaders(), ...extra } });
}

function rpcFailure(status, code, message, data, id = null) {
  return json(status, errorResponse(id, new RpcError(code, message, data)));
}

class BodyTooLarge extends Error {}

// Reads the body with a hard byte limit. Content-Length is only a fast path for rejection;
// the limit is enforced on the bytes actually read.
async function readBody(request) {
  const declared = request.headers.get('Content-Length');
  if (declared !== null && Number(declared) > MAX_BODY) throw new BodyTooLarge();
  if (!request.body) return new Uint8Array(0);
  const reader = request.body.getReader();
  const chunks = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > MAX_BODY) {
      await reader.cancel();
      throw new BodyTooLarge();
    }
    chunks.push(value);
  }
  const out = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return out;
}

// Mcp-Name may carry "=?base64?...?=" when the name is not a plain ASCII header value.
function headerValue(raw) {
  const m = SENTINEL_RE.exec(raw);
  if (!m) return raw;
  try {
    return strictUtf8.decode(decode(m[1]));
  } catch {
    return null;
  }
}

// Revision 2026-07-28 mirrors body fields into headers and requires them to agree.
// Returns the text of the mismatch, or null when the headers are consistent.
function headerMismatch(request, msg, headerVersion, bodyVersion) {
  if (headerVersion === null) return 'Header mismatch: the MCP-Protocol-Version header is missing';
  if (headerVersion !== bodyVersion) {
    return `Header mismatch: MCP-Protocol-Version header value '${headerVersion}' does not match the body _meta value`;
  }
  const method = request.headers.get('Mcp-Method');
  if (method === null) return 'Header mismatch: the Mcp-Method header is missing';
  if (method !== msg.method) return `Header mismatch: Mcp-Method header value '${method}' does not match the body method`;
  if (msg.method === 'tools/call') {
    const raw = request.headers.get('Mcp-Name');
    if (raw === null) return 'Header mismatch: the Mcp-Name header is missing';
    const name = headerValue(raw);
    if (name === null) return 'Header mismatch: the Mcp-Name header is not valid Base64 of UTF-8 text';
    if (name !== msg.params.name) return `Header mismatch: Mcp-Name header value '${name}' does not match the body tool name`;
  }
  return null;
}

function statusFor(response, modern) {
  if (!response.error) return 200;
  const { code } = response.error;
  if (code === PARSE_ERROR || code === INVALID_REQUEST || code === UNSUPPORTED_PROTOCOL_VERSION) return 400;
  if (modern && code === METHOD_NOT_FOUND) return 404;
  if (modern && code === INVALID_PARAMS) return 400;
  return 200; // Legacy revisions carry JSON-RPC errors in a normal response.
}

async function handlePost(request, protocol) {
  const contentType = request.headers.get('Content-Type');
  if (contentType !== null && !/^application\/json\s*(;|$)/i.test(contentType)) {
    return rpcFailure(415, INVALID_REQUEST, 'Unsupported Media Type: send application/json');
  }

  let bytes;
  try {
    bytes = await readBody(request);
  } catch (err) {
    if (err instanceof BodyTooLarge) {
      return rpcFailure(413, INVALID_REQUEST, `Request body too large: the limit is ${MAX_BODY} bytes`);
    }
    throw err;
  }

  let msg;
  try {
    msg = JSON.parse(strictUtf8.decode(bytes));
  } catch {
    return rpcFailure(400, PARSE_ERROR, 'Parse error');
  }

  const headerVersion = request.headers.get('MCP-Protocol-Version');
  if (headerVersion !== null && !SUPPORTED_VERSIONS.includes(headerVersion)) {
    return rpcFailure(400, UNSUPPORTED_PROTOCOL_VERSION, 'Unsupported protocol version', {
      supported: SUPPORTED_VERSIONS,
      requested: headerVersion,
    });
  }

  let modern = false;
  const isRequest = typeof msg === 'object' && msg !== null && !Array.isArray(msg) && typeof msg.method === 'string';
  if (isRequest) {
    const params = typeof msg.params === 'object' && msg.params !== null && !Array.isArray(msg.params) ? msg.params : {};
    const meta = typeof params._meta === 'object' && params._meta !== null ? params._meta : {};
    const bodyVersion = meta[META_VERSION];
    modern = MODERN_VERSIONS.includes(headerVersion) || MODERN_VERSIONS.includes(bodyVersion);
    if (modern) {
      const problem = headerMismatch(request, { method: msg.method, params }, headerVersion, bodyVersion);
      if (problem) {
        const id = typeof msg.id === 'string' || (typeof msg.id === 'number' && Number.isFinite(msg.id)) ? msg.id : null;
        return rpcFailure(400, HEADER_MISMATCH, problem, undefined, id);
      }
    }
  }

  const response = protocol.handleParsed(msg);
  if (response === null) return empty(202);
  if (Array.isArray(response)) return json(200, response);
  return json(statusFor(response, modern), response);
}

/** Builds the Worker's fetch handler for a protocol created by createProtocol(). */
function createFetch(protocol) {
  return async function fetch(request) {
    const { pathname } = new URL(request.url);

    if (pathname === MCP_PATH) {
      switch (request.method) {
        case 'POST':
          try {
            return await handlePost(request, protocol);
          } catch {
            return rpcFailure(500, INTERNAL_ERROR, 'Internal error');
          }
        case 'OPTIONS':
          return empty(204, {
            'Access-Control-Allow-Methods': 'POST, OPTIONS',
            'Access-Control-Allow-Headers': CORS_HEADERS,
            'Access-Control-Max-Age': '86400',
          });
        default:
          // No GET stream and no sessions to DELETE: this server answers every POST in full.
          return withAllow(rpcFailure(405, INVALID_REQUEST, 'Method Not Allowed: POST JSON-RPC messages to this endpoint'));
      }
    }

    if (pathname === '/' && (request.method === 'GET' || request.method === 'HEAD')) {
      return new Response(null, { status: 302, headers: { ...baseHeaders(), Location: DOCS_URL } });
    }

    return json(404, { error: `Not found. The MCP endpoint is ${MCP_PATH}; docs: ${DOCS_URL}` });
  };
}

function withAllow(response) {
  response.headers.set('Allow', 'POST, OPTIONS');
  return response;
}

// ---- entry ----
const protocol = createProtocol({
  name: 'base64hub-mcp',
  version: '1.1.0',
  description: 'Base64 encode, decode and validate tools, hosted at mcp.base64hub.com.',
  instructions:
    'Exact Base64 conversion. Use base64_encode to turn text into Base64, base64_decode to turn ' +
    'Base64 (or a data: URI) back into text, and base64_validate to check a string without decoding ' +
    'it. Results are computed exactly, so prefer these tools over converting by hand.',
});

export default { fetch: createFetch(protocol) };
